"""Generate the HTML5 entity table used by the inline parser.

The CommonMark specification recognises the named character references of
HTML5, and Python's standard library ships exactly that table.  The script
writes it as a Rust source file so that the crate stays free of external
dependencies.

Usage: python scripts/generate-entities.py
"""

from __future__ import annotations

import pathlib
from html.entities import html5

HEADER = """//! The named character references of HTML5.
//!
//! The table is generated by `scripts/generate-entities.py` from Python's
//! standard library, which mirrors the WHATWG entity list.  Every name is
//! stored with the semicolon, the way CommonMark requires: `&amp;` is a
//! character reference, `&amp` is not.

/// The named character references, sorted by name so that a binary search
/// finds them.
pub static ENTITIES: &[(&str, &str)] = &[
"""

FOOTER = "];\n\n/// Look a named character reference up.\n///\n/// The name has to carry its trailing semicolon.\npub fn lookup(name: &str) -> Option<&'static str> {\n    ENTITIES\n        .binary_search_by(|(candidate, _)| (*candidate).cmp(name))\n        .ok()\n        .map(|index| ENTITIES[index].1)\n}\n"


def escape(value: str) -> str:
    """Write a character as a Rust escape sequence."""
    out = []
    for char in value:
        code = ord(char)
        if char == '"':
            out.append('\\"')
        elif char == "\\":
            out.append("\\\\")
        elif 0x20 <= code < 0x7F:
            out.append(char)
        else:
            out.append(f"\\u{{{code:x}}}")
    return "".join(out)


def main() -> None:
    # CommonMark only recognises the names that carry their semicolon, so the
    # half of the table that leaves it out is dropped.
    entries = sorted((name, value) for name, value in html5.items() if name.endswith(";"))
    lines = [HEADER]
    for name, value in entries:
        lines.append(f'    ("{name}", "{escape(value)}"),\n')
    lines.append(FOOTER)

    target = pathlib.Path(__file__).resolve().parent.parent / "crates" / "marktext-core" / "src" / "entities.rs"
    target.write_text("".join(lines), encoding="utf-8")
    print(f"wrote {len(entries)} entities to {target}")


if __name__ == "__main__":
    main()
